import logging
import os

from ..racclimx import Racclimx
from .exceptions import OperationNotSupported

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class WorkflowEngine(Racclimx):

    def apply_site_templates(self, plan_name, verbose=True, ignore_errors=False, timeout=7200):
        """
        Apply the assigned site templates to the SBTS plan

        :param string plan_name: Specifies a plan name
        :param bool verbose: If True, returns a detailed output from executed operation
        :param bool ignore_errors: If True, shows warnings instead of raising errors when operation fails
        :param int timeout: Timeout for executing operation
        """
        name_of_plan_name_option = self._discover_name_of_plan_name_option()
        parameters = {
            '-op': 'Rebuild - Apply site templates',
            name_of_plan_name_option: plan_name
        }

        return self._execute_operation(parameters, verbose, ignore_errors, timeout)

    def _discover_name_of_plan_name_option(self):
        """
        NOTE: plan name option is '-mainPlanName' for some releases, and '-masterPlanName' for others
        """
        with self.ssh_cmwas_node as ssh:
            output = ssh.execute_command('racclimx.sh -op "Rebuild - Apply site templates" -h').stdout

        try:
            possible_names = ['-masterPlanName', '-mainPlanName']
            return next(name for name in possible_names if name in output)
        except StopIteration:
            msg = '"Rebuild - Apply site templates" is not part of the possible executable operations'
            raise OperationNotSupported(msg)

    def prepare_unified_pnp_coam_site(self,
                                      plan_name,
                                      input_file,
                                      file_format,
                                      profiler_file,
                                      activate_site_template,
                                      ui_values,
                                      gps_identification_used,
                                      gps_tolerance,
                                      maintenance_region_dn,
                                      verbose=True,
                                      ignore_errors=False,
                                      timeout=600,
                                      distribution=None,
                                      helm_test=None,
                                      local_dir=None,
                                      cleanup=True
                                      ):
        """
        This operation:
        1. Creates BTSs site plan
        2. Applies site template to the plan
        3. Validates the plan
        4. Sends identification parameters to AC Service.

        NetAct's default import directory ``/var/opt/oss/global/racops/import/``.

        :param string plan_name: Specifies a plan name
        :param string input_file: Specifies a full path to plan or a name of a plan inside Netact default import directory,
            or, when used with ``local_dir``, a name of a local plan file. If not provided,
            operation will be executed on the existing plan
        :param string file_format: Indicates the CSV or RAML2 file format with COAM BTS planned configuration.
            Defaults to RAML2
        :param string profiler_file: Profile file is required in case the CSV format is chosen.
            Defaults to `/var/opt/oss/global/racops/import/`
        :param bool activate_site_template: Specifies if Site Template is used in planning operation.
            Defaults to ``True``
        :param bool ui_values: Specifies if parameter values are given as UI values in an imported file with COAM BTS planned configuration.
            If this parameter is not defined, internal values are used.
            Defaults to ``False``
        :param bool gps_identification_used: Enable to using GPS based identification. Site object must to be assigned.
            Defaults to ``False``
        :param int gps_tolerance: Defines the allowed deviation (meter) between the reported GPS location of the NE
            and the location defined int Site object. Range: 1..5000.
            No default value
        :param string maintenance_region_dn: Defines DN of the Maintenance Region to be assigned to the NEs that do not have it specified
            in an imported file with planned configuration. An example of a valid format is ``MRC-1/MR-NE3S``.
            No default value
        :param bool verbose: If ``True``, method returns a detailed output from executed operation
        :param bool ignore_errors: If ``True``, method shows warnings instead of raising errors when operation fails
        :param int timeout: Timeout for executing command
        :param bool distribution: Allows to distribute CNF SW images to Container Registries before CNF deployment.
            ``True`` by default (provided that the option is supported by ``racclimx.sh``)
        :param bool helm_test: Specifies if helm test is performed during deployment of CNFs. ``True`` by default
        :param str local_dir: If provided, then the given ``input_file`` is copied from this path to NetAct's default import directory
            before executing the command
        :param bool cleanup: Specifies if the uploaded file has to be removed from NetAct upon completion
        """
        input_file_dir = os.path.dirname(input_file) if input_file else None
        remote_dir = None if input_file_dir else self.IMPORT_DIR
        file_name = os.path.basename(input_file) if input_file else None
        parameters = {
            '-op': 'Unified_PnP_COAM_Site_Preparation',
            '-planName': plan_name,
            '-inputFile': input_file,
            '-fileFormat': file_format,
            '-profileFile': profiler_file,
            '-activateSiteTemplate': activate_site_template,
            '-UIValues': ui_values,
            '-GPSIdentificationUsed': gps_identification_used,
            '-GPSTolerance': gps_tolerance,
            '-maintenanceRegionDn': maintenance_region_dn,
            '-distribution': distribution,
            '-helmTest': helm_test
        }

        return self._put_file_and_execute_operation(
            parameters, file_name, local_dir, remote_dir, cleanup, verbose, ignore_errors, timeout)
